class CustomerRepositoryTest {

    private QueryLog queryLog;
    private CustomerRepository repository;

    @BeforeEach
    void setUp() {
        queryLog = new QueryLog();
        repository = new CustomerRepository(queryLog);
    }

    @Test
    void theFilteredCountIsTheNumberOfMatchesNotTheRowsLoaded() {
        CustomerFilter filter = new CustomerFilter("makinen", Set.of());

        assertEquals(15, repository.count(filter));
        assertEquals(List.of(15), queryLog.countQueries());
    }

    @Test
    void aPageIsTakenFromTheMatches() {
        CustomerFilter filter = new CustomerFilter("makinen", Set.of(CustomerStatus.CLOSED));

        List<Customer> page = repository.findAll(filter, 0, 200, List.of(new CustomerSort("id", true)));

        assertEquals(repository.count(filter), page.size());
        assertTrue(page.stream().allMatch(filter.predicate()));
    }

    @Test
    void sortingAppliesWhileFiltered() {
        CustomerFilter filter = new CustomerFilter("", Set.of(CustomerStatus.PENDING));

        List<Customer> page = repository.findAll(filter, 0, 5, List.of(new CustomerSort("lastName", false)));

        assertEquals(5, page.size());
        for (int i = 1; i < page.size(); i++) {
            assertTrue(page.get(i - 1).lastName().compareToIgnoreCase(page.get(i).lastName()) >= 0,
                    "rows must be sorted by last name, descending");
        }
    }

    @Test
    void theFilteredPageStillRefusesMoreThanTheMaximum() {
        CustomerFilter filter = new CustomerFilter("", Set.of());

        assertThrows(IllegalArgumentException.class,
                () -> repository.findAll(filter, 0, CustomerRepository.MAX_PAGE_SIZE + 1, List.of()));
    }

    @Test
    void everyFilteredQueryIsRecordedOnce() {
        CustomerFilter filter = new CustomerFilter("ada", Set.of());

        repository.count(filter);
        repository.findAll(filter, 0, 10, List.of());

        assertEquals(1, queryLog.countQueries().size());
        assertEquals(1, queryLog.pageQueries().size());
        assertEquals(new QueryLog.PageQuery(0, 10, queryLog.pageQueries().get(0).rowsReturned()),
                queryLog.pageQueries().get(0));
    }
}
