+package com.example.customers.domain;
+
+import java.text.Normalizer;
+import java.util.List;
+import java.util.Locale;
+import java.util.Set;
+import java.util.function.Predicate;
+import java.util.regex.Pattern;
+
+/**
+ * The criteria a customer list is narrowed by. A customer is shown when it
+ * satisfies both of them.
+ *
+ * <ul>
+ *   <li><b>Name:</b> the text is split on whitespace into terms, and every term
+ *       must be a substring of the first name or of the last name. Case and
+ *       accents are ignored on both sides, so {@code makinen} matches
+ *       {@code Mäkinen}.</li>
+ *   <li><b>Status:</b> with no statuses selected every status matches; otherwise
+ *       the customer's status must be one of the selected ones.</li>
+ * </ul>
+ *
+ * @param name     the text typed into the name filter; blank means no name filter
+ * @param statuses the statuses selected; empty means every status
+ */
+public record CustomerFilter(String name, Set<CustomerStatus> statuses) {
+
+    /** The filter that matches every customer. */
+    public static final CustomerFilter NONE = new CustomerFilter("", Set.of());
+
+    private static final Pattern WHITESPACE = Pattern.compile("\\s+", Pattern.UNICODE_CHARACTER_CLASS);
+    private static final Pattern COMBINING_MARKS = Pattern.compile("\\p{M}+");
+
+    public CustomerFilter {
+        name = (name == null) ? "" : name;
+        statuses = (statuses == null) ? Set.of() : Set.copyOf(statuses);
+    }
+
+    /** Returns a test for the customers this filter accepts. */
+    public Predicate<Customer> predicate() {
+        List<String> terms = WHITESPACE.splitAsStream(fold(name))
+                .filter(term -> !term.isEmpty())
+                .toList();
+        return customer -> (statuses.isEmpty() || statuses.contains(customer.status()))
+                && nameMatches(customer, terms);
+    }
+
+    private static boolean nameMatches(Customer customer, List<String> terms) {
+        String firstName = fold(customer.firstName());
+        String lastName = fold(customer.lastName());
+        return terms.stream().allMatch(term -> firstName.contains(term) || lastName.contains(term));
+    }
+
+    /** Lower-cases {@code text} and strips accents, so that comparisons ignore both. */
+    private static String fold(String text) {
+        String decomposed = Normalizer.normalize(text, Normalizer.Form.NFD);
+        return COMBINING_MARKS.matcher(decomposed).replaceAll("").toLowerCase(Locale.ROOT);
+    }
+}
