+    void nameTermsMayComeInAnyOrderAndWhitespaceIsInsignificant() {
+        _setValue(nameFilter(), "aal ada");
+        assertEquals(2, _size(grid()));
+
+        _setValue(nameFilter(), "  ada   aal  ");
+        assertEquals(2, _size(grid()));
+    }
+
+    @Test
+    void nameMatchesNobodyWhenATermMatchesNeitherName() {
+        _setValue(nameFilter(), "ada virtanen");
+
+        assertEquals(0, _size(grid()));
+        assertEquals("Showing 0 of 500", summary());
+    }
+
+    @Test
+    void nameIgnoresCaseAndAccentsInBothDirections() {
+        _setValue(nameFilter(), "makinen");
+        assertEquals(15, _size(grid()));
+
+        _setValue(nameFilter(), "MAKINEN");
+        assertEquals(15, _size(grid()));
+
+        _setValue(nameFilter(), "mäkinen");
+        assertEquals(15, _size(grid()));
+
+        _setValue(nameFilter(), "josephine");
+        assertEquals(12, _size(grid()));
+    }
+
+    @Test
+    void statusFilterKeepsOnlyTheSelectedStatuses() {
+        _setValue(statusFilter(), Set.of(CustomerStatus.ACTIVE));
+        assertEquals(167, _size(grid()));
+
+        _setValue(statusFilter(), Set.of(CustomerStatus.ACTIVE, CustomerStatus.CLOSED));
+        assertEquals(333, _size(grid()));
+        assertEquals("Showing 333 of 500", summary());
+    }
+
+    @Test
+    void bothFiltersApplyTogether() {
+        _setValue(nameFilter(), "makinen");
+        _setValue(statusFilter(), Set.of(CustomerStatus.ACTIVE, CustomerStatus.CLOSED));
+
+        assertEquals(10, _size(grid()));
+        assertEquals("Showing 10 of 500", summary());
+        assertFalse(gridRows().stream().anyMatch(row -> row.get(4).equals("PENDING")));
+    }
+
+    @Test
+    void clearingTheFiltersShowsEveryCustomerAgain() {
+        _setValue(nameFilter(), "makinen");
+        _setValue(statusFilter(), Set.of(CustomerStatus.PENDING));
+        _setValue(nameFilter(), "");
+        _setValue(statusFilter(), Set.of());
+
+        assertEquals(500, _size(grid()));
+        assertEquals("Showing 500 of 500", summary());
+    }
+
+    /**
+     * The count is the backend's count of every match, not the rows the grid has
+     * loaded: 167 customers are active, far more than one page of rows holds.
+     */
+    @Test
+    void theMatchingCountComesFromTheBackend() {
+        _setValue(statusFilter(), Set.of(CustomerStatus.ACTIVE));
+
+        assertTrue(queryLog.countQueries().contains(167),
+                "The backend must count every match: " + queryLog.countQueries());
+        assertEquals("Showing 167 of 500", summary());
+    }
+
+    /**
+     * Typing a name must cost one count and one page of rows, however often the grid
+     * asks for its size during the refresh.
+     */
+    @Test
+    void aFilterChangeCostsOneCountAndOnePageOfRows() {
+        grid();
+        MockVaadin.clientRoundtrip();
+        queryLog.clear();
+
+        _setValue(nameFilter(), "ada aal");
+        MockVaadin.clientRoundtrip();
+
+        assertEquals(1, queryLog.countQueries().size(),
+                "One filter change must ask the backend for the count once: " + queryLog.countQueries());
+        assertEquals(1, queryLog.pageQueries().size(),
+                "One filter change must fetch one page of rows: " + queryLog.pageQueries());
+        queryLog.pageQueries().forEach(page -> assertTrue(page.limit() <= CustomerRepository.MAX_PAGE_SIZE));
+    }
+
+    @Test
+    void sortingKeepsWorkingWhileFiltered() {
+        _setValue(nameFilter(), "tomas");
+        _setValue(statusFilter(), Set.of(CustomerStatus.PENDING));
+        Grid<?> grid = grid();
+
+        sortByLastName(grid, SortDirection.ASCENDING);
+        assertEquals(List.of("Boisvert", "Castellanos", "Halonen", "Mäkinen", "Wallenberg"),
+                lastNames(grid, 5));
+
+        sortByLastName(grid, SortDirection.DESCENDING);
+        assertEquals(List.of("Wallenberg", "Mäkinen", "Halonen", "Castellanos", "Boisvert"),
+                lastNames(grid, 5));
+    }
+
+    @Test
+    void readsTheFiltersFromTheUrl() {
+        navigateTo("name=vir&status=ACTIVE,CLOSED");
+
+        assertEquals("vir", nameFilter().getValue());
+        assertEquals(Set.of(CustomerStatus.ACTIVE, CustomerStatus.CLOSED), statusFilter().getValue());
+        assertEquals(10, _size(grid()));
+        assertEquals("Showing 10 of 500", summary());
+    }
+
+    @Test
+    void anUrlWithoutParametersLeavesTheFilterEmpty() {
+        navigateTo("name=vir&status=PENDING");
+        navigateTo("");
+
+        assertEquals("", nameFilter().getValue());
+        assertTrue(statusFilter().getValue().isEmpty());
+        assertEquals("Showing 500 of 500", summary());
+    }
+
+    private static void navigateTo(String queryString) {
+        UI.getCurrent().navigate("", QueryParameters.fromString(queryString));
+    }
+
+    private static TextField nameFilter() {
+        return _get(TextField.class, spec -> spec.withPlaceholder("Filter by name"));
+    }
+
+    @SuppressWarnings("unchecked")
+    private static MultiSelectComboBox<CustomerStatus> statusFilter() {
+        return _get(MultiSelectComboBox.class, spec -> spec.withLabel("Status"));
+    }
+
+    private static Grid<?> grid() {
+        return _get(Grid.class);
+    }
+
+    private static String summary() {
+        return _find(Span.class).stream()
+                .map(Span::getText)
+                .filter(text -> text.startsWith("Showing "))
+                .findFirst()
+                .orElseThrow();
+    }
+
+    private static List<List<String>> gridRows() {
+        Grid<?> grid = grid();
+        return IntStream.range(0, _size(grid))
+                .mapToObj(row -> _getFormattedRow(grid, row))
+                .toList();
+    }
+
+    private static <T> void sortByLastName(Grid<T> grid, SortDirection direction) {
+        grid.sort(List.of(new GridSortOrder<>(grid.getColumnByKey("lastName"), direction)));
+    }
+
+    private static List<String> lastNames(Grid<?> grid, int rows) {
+        return IntStream.range(0, rows)
+                .mapToObj(row -> _getFormattedRow(grid, row).get(1))
+                .toList();
+    }
 }
diff --git a/src/test/java/com/example/customers/domain/CustomerFilterTest.java b/src/test/java/com/example/customers/domain/CustomerFilterTest.java
new file mode 100644
index 0000000..23447b4
--- /dev/null
+++ b/src/test/java/com/example/customers/domain/CustomerFilterTest.java
@@ -0,0 +1,67 @@
+package com.example.customers.domain;
+
+import static com.example.customers.domain.CustomerStatus.ACTIVE;
+import static com.example.customers.domain.CustomerStatus.CLOSED;
+import static com.example.customers.domain.CustomerStatus.PENDING;
+import static org.junit.jupiter.api.Assertions.assertFalse;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+import java.util.Set;
+
+import org.junit.jupiter.api.Test;
+
+class CustomerFilterTest {
+
+    private static final Customer ADA = new Customer(1, "Ada", "Aaltonen", "ada@example.com", "Finland", ACTIVE);
+    private static final Customer JARNO = new Customer(2, "Jarno", "Mäkinen", "jarno@example.com", "Finland", PENDING);
+    private static final Customer JOSEPHINE = new Customer(3, "Joséphine", "Engberg", "j@example.com", "Denmark", CLOSED);
+
+    private static boolean matches(String name, Customer customer) {
+        return new CustomerFilter(name, Set.of()).predicate().test(customer);
+    }
+
+    @Test
+    void aBlankNameMatchesEveryone() {
+        assertTrue(matches("", ADA));
+        assertTrue(matches("   ", ADA));
+        assertTrue(matches(null, ADA));
+    }
+
+    @Test
+    void everyTermMustMatchAFirstOrLastName() {
+        assertTrue(matches("ada aal", ADA));
+        assertTrue(matches("aal ada", ADA));
+        assertTrue(matches("  ada   aal  ", ADA));
+        assertFalse(matches("ada virtanen", ADA));
+    }
+
+    @Test
+    void termsMatchSubstrings() {
+        assertTrue(matches("ltonen", ADA));
+        assertTrue(matches("a", ADA));
+    }
+
+    @Test
+    void caseAndAccentsAreIgnoredInBothDirections() {
+        assertTrue(matches("makinen", JARNO));
+        assertTrue(matches("MAKINEN", JARNO));
+        assertTrue(matches("mäkinen", JARNO));
+        assertTrue(matches("josephine", JOSEPHINE));
+        assertTrue(matches("Joséphine", JOSEPHINE));
+        assertTrue(matches("JOSEPHINE", JOSEPHINE));
+    }
+
+    @Test
+    void theStatusFilterKeepsOnlyTheSelectedStatuses() {
+        assertTrue(new CustomerFilter("", Set.of(ACTIVE, CLOSED)).predicate().test(ADA));
+        assertFalse(new CustomerFilter("", Set.of(ACTIVE, CLOSED)).predicate().test(JARNO));
+        assertTrue(new CustomerFilter("", Set.of()).predicate().test(JARNO));
+    }
+
+    @Test
+    void theNameAndStatusFiltersBothApply() {
+        assertTrue(new CustomerFilter("makinen", Set.of(PENDING)).predicate().test(JARNO));
+        assertFalse(new CustomerFilter("makinen", Set.of(ACTIVE)).predicate().test(JARNO));
+        assertFalse(new CustomerFilter("ada", Set.of(PENDING)).predicate().test(JARNO));
+    }
+}
diff --git a/src/test/java/com/example/customers/domain/CustomerRepositoryTest.java b/src/test/java/com/example/customers/domain/CustomerRepositoryTest.java
new file mode 100644
index 0000000..4906374
--- /dev/null
+++ b/src/test/java/com/example/customers/domain/CustomerRepositoryTest.java
@@ -0,0 +1,75 @@
+package com.example.customers.domain;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertThrows;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+import java.util.List;
+import java.util.Set;
+
+import org.junit.jupiter.api.BeforeEach;
+import org.junit.jupiter.api.Test;
+
+class CustomerRepositoryTest {
+
+    private QueryLog queryLog;
+    private CustomerRepository repository;
+
+    @BeforeEach
+    void setUp() {
+        queryLog = new QueryLog();
+        repository = new CustomerRepository(queryLog);
+    }
+
+    @Test
+    void countIsTheNumberOfMatchesAcrossTheWholeDataSet() {
+        CustomerFilter filter = new CustomerFilter("makinen", Set.of());
+
+        assertEquals(15, repository.count(filter));
+        assertEquals(List.of(15), queryLog.countQueries());
+    }
+
+    @Test
+    void aPageIsTakenFromTheMatches() {
+        CustomerFilter filter = new CustomerFilter("makinen", Set.of(CustomerStatus.CLOSED));
+
+        List<Customer> page = repository.findAll(filter, 0, 200, List.of(new CustomerSort("id", true)));
+
+        assertEquals(repository.count(filter), page.size());
+        assertTrue(page.stream().allMatch(filter.predicate()));
+    }
+
+    @Test
+    void sortingAppliesWhileFiltered() {
+        CustomerFilter filter = new CustomerFilter("", Set.of(CustomerStatus.PENDING));
+
+        List<Customer> page = repository.findAll(filter, 0, 5, List.of(new CustomerSort("lastName", false)));
+
+        assertEquals(5, page.size());
+        for (int i = 1; i < page.size(); i++) {
+            assertTrue(page.get(i - 1).lastName().compareToIgnoreCase(page.get(i).lastName()) >= 0,
+                    "rows must be sorted by last name, descending");
+        }
+    }
+
+    @Test
+    void theFilteredPageStillRefusesMoreThanTheMaximum() {
+        CustomerFilter filter = new CustomerFilter("", Set.of());
+
+        assertThrows(IllegalArgumentException.class,
+                () -> repository.findAll(filter, 0, CustomerRepository.MAX_PAGE_SIZE + 1, List.of()));
+    }
+
+    @Test
+    void everyFilteredQueryIsRecordedOnce() {
+        CustomerFilter filter = new CustomerFilter("ada", Set.of());
+
+        repository.count(filter);
+        repository.findAll(filter, 0, 10, List.of());
+
+        assertEquals(1, queryLog.countQueries().size());
+        assertEquals(1, queryLog.pageQueries().size());
+        assertEquals(0, queryLog.pageQueries().get(0).offset());
+        assertEquals(10, queryLog.pageQueries().get(0).limit());
+    }
+}
